#!/bin/sh
# AUTOGENERATED COPYRIGHT HEADER START
# Copyright (C) 2026 Narta Xaymar Dirks <info@xaymar.com>
# AUTOGENERATED COPYRIGHT HEADER END
# BlitzLLVM for Linux: a self-installing archive. The prebuilt BlitzLLVM (the same files as the .tar.gz) is appended to this script and is
# unpacked by it; nothing is compiled. BlitzLLVM needs clang 21 or newer (and lld) to build programs, which this script can install too.
#
#   sh blitzllvm-<version>-linux-<arch>-installer.sh [options]
#     --prefix <dir>     Install into <dir>/opt/blitzllvm, with the commands in <dir>/bin. Default: ~/.local (no root needed).
#     --install-clang    Install clang and lld with the package manager of the distribution (apt, dnf, pacman or zypper; asks sudo).
#     --uninstall        Remove what an earlier run installed into the prefix.
#     --extract <dir>    Only unpack the files into <dir>.
#     --help             Show this.
set -eu

prefix="$HOME/.local"
install_clang=0
mode=install
extract_dir=
while [ $# -gt 0 ]; do
	case "$1" in
		--prefix) prefix="${2:?--prefix needs a folder}"; shift ;;
		--prefix=*) prefix="${1#--prefix=}" ;;
		--install-clang) install_clang=1 ;;
		--uninstall) mode=uninstall ;;
		--extract) mode=extract; extract_dir="${2:?--extract needs a folder}"; shift ;;
		--help|-h) awk '/^# BlitzLLVM for Linux/ { p = 1 } /^set -eu$/ { exit } p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
		*) echo "Unknown option '$1' (see --help)." >&2; exit 2 ;;
	esac
	shift
done

dest="$prefix/opt/blitzllvm"
tools="blitzcc blitz-format blitz-tidy blitz-recompiler blitz-lsp"

unpack() {
	# The archive starts on the line after the marker; the marker is found by its line number, so the script can't match itself.
	line=$(awk '/^__BLITZLLVM_ARCHIVE_BELOW__$/ { print NR + 1; exit }' "$0")
	tail -n +"$line" "$0" | tar -xzf - -C "$1" --strip-components=1
}

# A clang of version 21 or newer: plain 'clang' first, then the versioned names that apt.llvm.org and some distributions use.
find_clang() {
	for cc in clang clang-30 clang-29 clang-28 clang-27 clang-26 clang-25 clang-24 clang-23 clang-22 clang-21; do
		path=$(command -v "$cc" 2>/dev/null) || continue
		major=$("$path" --version 2>/dev/null | sed -n 's/.*clang version \([0-9][0-9]*\).*/\1/p' | head -n 1)
		if [ "${major:-0}" -ge 21 ]; then echo "$path"; return 0; fi
	done
	return 1
}

clang_command() {
	if command -v apt-get >/dev/null 2>&1; then
		if apt-cache show clang-21 >/dev/null 2>&1; then
			echo "sudo apt-get install -y clang-21 lld-21"
		else
			# Older Ubuntu and Debian: the packages of the LLVM project (https://apt.llvm.org).
			echo "wget -qO /tmp/llvm.sh https://apt.llvm.org/llvm.sh && sudo bash /tmp/llvm.sh 21"
		fi
	elif command -v dnf >/dev/null 2>&1; then echo "sudo dnf install -y clang lld"
	elif command -v pacman >/dev/null 2>&1; then echo "sudo pacman -S --needed --noconfirm clang lld"
	elif command -v zypper >/dev/null 2>&1; then echo "sudo zypper install -y clang lld"
	else return 1
	fi
}

case "$mode" in
	extract)
		mkdir -p "$extract_dir"
		unpack "$extract_dir"
		echo "Unpacked BlitzLLVM into $extract_dir."
		exit 0 ;;
	uninstall)
		for tool in $tools; do
			# Only the links and the launcher that point into our folder.
			if [ -L "$prefix/bin/$tool" ] || grep -qs "$dest/bin/" "$prefix/bin/$tool"; then rm -f "$prefix/bin/$tool"; fi
		done
		rm -rf "$dest"
		echo "Removed BlitzLLVM from $prefix."
		exit 0 ;;
esac

if [ "$install_clang" = 1 ] && ! find_clang >/dev/null; then
	command=$(clang_command) || { echo "No apt, dnf, pacman or zypper found: install clang 21 or newer and lld yourself." >&2; exit 1; }
	echo "Installing clang: $command"
	sh -c "$command"
fi

# An update replaces the whole folder, so no file of the older version is left behind.
rm -rf "$dest.new"
mkdir -p "$dest.new" "$prefix/bin"
unpack "$dest.new"
rm -rf "$dest"
mv "$dest.new" "$dest"

for tool in $tools; do
	[ -e "$dest/bin/$tool" ] || continue
	rm -f "$prefix/bin/$tool"
	ln -s "$dest/bin/$tool" "$prefix/bin/$tool"
done

# blitzcc calls 'clang'. Where the clang of version 21 or newer has another name (clang-21), a launcher tells blitzcc which one.
cc=$(find_clang || true)
if [ -n "$cc" ] && [ "$(basename "$cc")" != clang ]; then
	rm -f "$prefix/bin/blitzcc"
	printf '#!/bin/sh\n# Made by the BlitzLLVM installer: uses %s unless BLITZLLVM_CC says otherwise.\nBLITZLLVM_CC="${BLITZLLVM_CC:-%s}" exec "%s" "$@"\n' "$cc" "$cc" "$dest/bin/blitzcc" > "$prefix/bin/blitzcc"
	chmod +x "$prefix/bin/blitzcc"
fi

echo "Installed BlitzLLVM into $dest, the commands are in $prefix/bin."
case ":$PATH:" in *":$prefix/bin:"*) ;; *) echo "Add $prefix/bin to your PATH to run blitzcc by its name." ;; esac
if [ -n "$cc" ]; then
	echo "Programs are built with $cc."
else
	echo "clang 21 or newer was not found. BlitzLLVM needs it to build programs. Run this again with --install-clang, or install it with:"
	echo "  $(clang_command || echo 'the package manager of your distribution (clang and lld)')"
fi
exit 0
__BLITZLLVM_ARCHIVE_BELOW__
